"use client";

import { forwardRef, useEffect, useRef, useState, type PointerEvent as ReactPointerEvent, type ReactNode } from "react";
import {
  Button as AriaButton,
  Dialog as AriaDialog,
  Heading,
  Modal,
  ModalOverlay,
  type DialogProps as AriaDialogProps,
} from "react-aria-components";
import { drawerDefaults, type DrawerSpecProps } from "../generated/drawer.types";
import { cx } from "../utils/cx";
import { clampIndex, cleanSnapPoints, dragHeight, resolveSnap, snapHeights, stepIndex } from "./snap";

export interface DrawerProps
  extends DrawerSpecProps,
    Omit<AriaDialogProps, keyof DrawerSpecProps | "className" | "children"> {
  className?: string;
  /** Controlled open state, for drawers opened without a DialogTrigger. */
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
}

const keyframes = `
@keyframes rd-drawer-up { from { transform: translateY(100%); } }
@keyframes rd-drawer-fade { from { opacity: 0; } }`;

/** A drag past this many pixels, or this share of the height, dismisses. */
const DISMISS_PX = 96;
const DISMISS_RATIO = 0.3;
const FLICK_PX_PER_MS = 0.6;

const words = { expand: "Expand", collapse: "Collapse", expanded: "Expanded", collapsed: "Collapsed" } as const;

/** What the panel needs to rest at several heights. Absent when the drawer has no snap points. */
interface SnapControl {
  heights: number[];
  index: number;
  /** The live height while the finger is down, or null at rest. */
  setLive: (height: number | null) => void;
  /** Settle on a snap point (a number) or close (null). */
  commit: (index: number | null) => void;
  labels: Record<keyof typeof words, string>;
  announcement: string;
  /** The height the sheet is showing now. */
  height: number;
}

interface PanelProps {
  title?: string;
  description?: string;
  isDismissable: boolean;
  setDrag: (dy: number) => void;
  setDragging: (on: boolean) => void;
  close: () => void;
  snap?: SnapControl;
  onOpened: () => void;
  children: ReactNode;
}

function Panel({ title, description, isDismissable, setDrag, setDragging, close, snap, onOpened, children }: PanelProps) {
  const start = useRef<{ y: number; t: number; id: number; height: number; base: number; last: number; lastT: number; speed: number } | null>(null);

  // A new open always starts at rest.
  useEffect(() => {
    setDrag(0);
    setDragging(false);
    snap?.setLive(null);
    onOpened();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!isDismissable || (e.pointerType === "mouse" && e.button !== 0)) return;
    const panel = e.currentTarget.closest<HTMLElement>("[data-rd-drawer]");
    const base = snap?.height ?? 0;
    start.current = { y: e.clientY, t: e.timeStamp, id: e.pointerId, height: panel?.offsetHeight ?? 400, base, last: base, lastT: e.timeStamp, speed: 0 };
    e.currentTarget.setPointerCapture?.(e.pointerId);
    setDragging(true);
  };
  const onMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    const s = start.current;
    if (!s || e.pointerId !== s.id) return;
    if (snap) {
      // Dragging up makes the sheet taller; the speed is kept for the flick.
      const next = dragHeight(s.base, s.y - e.clientY, snap.heights, isDismissable);
      s.speed = (next - s.last) / Math.max(1, e.timeStamp - s.lastT);
      s.last = next;
      s.lastT = e.timeStamp;
      snap.setLive(next);
      return;
    }
    // Only downward movement counts; the panel never lifts above rest.
    setDrag(Math.max(0, e.clientY - s.y));
  };
  const finish = (e: ReactPointerEvent<HTMLDivElement>, cancelled: boolean) => {
    const s = start.current;
    if (!s || e.pointerId !== s.id) return;
    start.current = null;
    setDragging(false);
    if (snap) {
      snap.setLive(null);
      if (cancelled) return;
      snap.commit(resolveSnap({ height: s.last, velocity: s.speed, heights: snap.heights, dismissable: isDismissable }).index);
      return;
    }
    const dy = Math.max(0, e.clientY - s.y);
    const speed = dy / Math.max(1, e.timeStamp - s.t);
    if (!cancelled && (dy > Math.min(DISMISS_PX, Math.max(48, s.height * DISMISS_RATIO)) || (dy > 24 && speed > FLICK_PX_PER_MS))) {
      close();
    } else {
      setDrag(0);
    }
  };

  const top = snap ? snap.index === snap.heights.length - 1 : false;

  return (
    <>
      {/* The handle and header are the drag surface. Touch scrolling is off there so the browser does not take the gesture. */}
      <div
        className={cx("relative shrink-0 touch-none select-none", isDismissable && "cursor-grab active:cursor-grabbing")}
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={(e) => finish(e, false)}
        onPointerCancel={(e) => finish(e, true)}
      >
        {snap && snap.heights.length > 1 && (
          // The keyboard and screen reader way to change the height; it shows when it has focus.
          <>
            <AriaButton
              onPointerDown={(e) => e.stopPropagation()}
              onPress={() => snap.commit(top ? 0 : stepIndex(snap.index, snap.heights.length, 1))}
              onKeyDown={(e) => {
                if (e.key === "ArrowUp" || e.key === "ArrowDown") {
                  e.preventDefault();
                  snap.commit(stepIndex(snap.index, snap.heights.length, e.key === "ArrowUp" ? 1 : -1));
                }
              }}
              className={cx(
                "sr-only data-[focus-visible]:not-sr-only data-[focus-visible]:absolute data-[focus-visible]:end-3 data-[focus-visible]:top-2 data-[focus-visible]:z-10",
                "rounded-[var(--rd-radius-control)] border border-[var(--rd-color-border-default)] bg-[var(--rd-color-surface-raised)] px-3 py-1.5 text-xs font-medium text-[var(--rd-color-text-default)]",
                "outline-none data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]",
              )}
            >
              {top ? snap.labels.collapse : snap.labels.expand}
            </AriaButton>
            <span role="status" className="sr-only">
              {snap.announcement}
            </span>
          </>
        )}
        <div aria-hidden="true" className="flex justify-center pb-2 pt-3">
          <span className="h-1.5 w-10 rounded-full bg-[var(--rd-color-border-strong)]" />
        </div>
        {(title || description) && (
          <div className="flex flex-col gap-1 px-6 pb-4">
            {title && (
              <Heading slot="title" className="text-lg font-semibold">
                {title}
              </Heading>
            )}
            {description && <p className="text-sm text-[var(--rd-color-text-muted)]">{description}</p>}
          </div>
        )}
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto px-6 pb-6 pt-2 [overscroll-behavior:contain]" data-rd-drawer-body>
        {children}
      </div>
    </>
  );
}

/** The space a drawer may fill: the container it is drawn in, or the screen. */
function availableSpace(container: Element | null | undefined) {
  if (container) return container.clientHeight;
  return typeof window === "undefined" ? 0 : window.innerHeight;
}

export const Drawer = forwardRef<HTMLElement, DrawerProps>(function Drawer(
  {
    title,
    description,
    isDismissable = drawerDefaults.isDismissable,
    portalContainer,
    snapPoints,
    snap,
    defaultSnap = drawerDefaults.defaultSnap,
    onSnapChange,
    labels,
    isOpen,
    onOpenChange,
    children,
    className,
    ...rest
  },
  ref,
) {
  const [drag, setDrag] = useState(0);
  const [dragging, setDragging] = useState(false);

  // Resting at several heights: the points, the space they are shares of, and which one is showing.
  const points = cleanSnapPoints(snapPoints);
  const snapMode = points.length > 0;
  const [space, setSpace] = useState(() => availableSpace(portalContainer));
  useEffect(() => {
    if (!snapMode) return;
    const measure = () => setSpace(availableSpace(portalContainer));
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [snapMode, portalContainer]);
  const heights = snapHeights(points, space);
  const [inner, setInner] = useState(defaultSnap);
  const controlled = snap !== undefined;
  const index = clampIndex(controlled ? snap : inner, points.length);
  const [live, setLive] = useState<number | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const text = { ...words, ...labels };

  const showing = live ?? heights[index] ?? 0;

  return (
    <ModalOverlay
      isDismissable={isDismissable}
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      UNSTABLE_portalContainer={portalContainer ?? undefined}
      className={cx(portalContainer ? "absolute" : "fixed", "inset-0 z-50 bg-[var(--rd-color-overlay-backdrop)] backdrop-blur-[2px] data-[entering]:animate-[rd-drawer-fade_200ms] motion-reduce:animate-none")}
    >
      <style>{keyframes}</style>
      <Modal
        data-rd-drawer=""
        data-snap={snapMode ? index : undefined}
        style={snapMode ? { height: showing } : { transform: drag ? `translateY(${drag}px)` : undefined }}
        className={cx(
          portalContainer ? "absolute" : "fixed",
          "inset-x-0 bottom-0 flex w-full flex-col overflow-hidden rounded-t-[var(--rd-radius-overlay)] border-t",
          snapMode ? "max-h-full" : "max-h-[90dvh]",
          "[box-shadow:var(--rd-elevation-overlay)] bg-[var(--rd-color-surface-raised)] text-[var(--rd-color-text-default)] border-[var(--rd-color-border-default)]",
          "data-[entering]:animate-[rd-drawer-up_200ms_ease-out] motion-reduce:!animate-none",
          dragging ? "transition-none" : "transition-[height,transform] duration-200 ease-out motion-reduce:transition-none",
        )}
      >
        <AriaDialog {...rest} ref={ref} className={cx("flex min-h-0 flex-1 flex-col outline-none", className)}>
          {(renderProps) => (
            <Panel
              title={title}
              description={description}
              isDismissable={isDismissable}
              setDrag={setDrag}
              setDragging={setDragging}
              close={renderProps.close}
              onOpened={() => {
                if (!controlled) setInner(defaultSnap);
                setAnnouncement("");
              }}
              snap={
                snapMode
                  ? {
                      heights,
                      index,
                      height: showing,
                      setLive,
                      labels: text,
                      announcement,
                      commit: (next) => {
                        if (next === null) {
                          renderProps.close();
                          return;
                        }
                        if (next !== index) {
                          if (!controlled) setInner(next);
                          onSnapChange?.(next);
                          setAnnouncement(next > index ? text.expanded : text.collapsed);
                        }
                      },
                    }
                  : undefined
              }
            >
              {typeof children === "function" ? children(renderProps) : children}
            </Panel>
          )}
        </AriaDialog>
      </Modal>
    </ModalOverlay>
  );
});

// The arithmetic of a sheet that rests at several heights, with no React and no DOM, so it can be
// tested without a browser. Heights are in pixels; a drag up makes the sheet taller.

/** How long a flick carries on after the finger lifts, in milliseconds of travel at the release speed. */
export const PROJECTION_MS = 150;
/** Slower than this (px per ms) a release is a drag, not a flick. */
export const FLICK_SPEED = 0.4;
/** The lowest and highest share of the space a snap point may take. */
export const MIN_SNAP = 0.1;
export const MAX_SNAP = 1;

/**
 * The snap points as people may set them (shares of the available height, such as 0.4 and 0.9), made safe:
 * numbers only, kept inside 0.1 to 1, smallest first, without repeats.
 */
export function cleanSnapPoints(points: readonly number[] | undefined): number[] {
  if (!points) return [];
  const safe = points.filter((p) => Number.isFinite(p)).map((p) => Math.min(MAX_SNAP, Math.max(MIN_SNAP, p)));
  return Array.from(new Set(safe)).sort((a, b) => a - b);
}

/** The resting heights in pixels for the available space. */
export const snapHeights = (points: readonly number[], space: number): number[] => points.map((p) => Math.round(p * space));

/** A snap index kept inside the list. */
export const clampIndex = (index: number, count: number) => (count <= 0 ? 0 : Math.min(count - 1, Math.max(0, Math.round(index))));

/**
 * The height while the finger is down. Above the tallest snap the sheet stretches a little and pulls
 * back; below the shortest it follows the finger down, to nothing, when it can be dismissed and stops at
 * the shortest when it cannot.
 */
export function dragHeight(base: number, travelUp: number, heights: readonly number[], dismissable: boolean): number {
  const raw = base + travelUp;
  const lowest = heights[0] ?? 0;
  const highest = heights[heights.length - 1] ?? 0;
  if (raw > highest) return highest + Math.min(raw - highest, 24) * 0.35;
  if (raw < lowest) return dismissable ? Math.max(0, raw) : lowest;
  return raw;
}

export interface SnapRelease {
  /** The snap point to settle on, or null to close the sheet. */
  index: number | null;
}

/**
 * What happens when the finger lifts. A flick carries the sheet on a little, then it settles on the
 * nearest snap point. If it ends up well below the shortest one and the sheet can be dismissed, it closes.
 * `velocity` is px per ms, positive when the sheet was moving up.
 */
export function resolveSnap(input: { height: number; velocity: number; heights: readonly number[]; dismissable: boolean }): SnapRelease {
  const { height, velocity, heights, dismissable } = input;
  if (heights.length === 0) return { index: 0 };
  const projected = Math.abs(velocity) >= FLICK_SPEED ? height + velocity * PROJECTION_MS : height;
  const lowest = heights[0];
  // Past halfway between the shortest height and nothing: let it go.
  if (dismissable && projected < lowest * 0.5) return { index: null };
  let best = 0;
  for (let i = 1; i < heights.length; i++) if (Math.abs(heights[i] - projected) < Math.abs(heights[best] - projected)) best = i;
  return { index: best };
}

/** The next snap point up or down from this one, staying inside the list. */
export const stepIndex = (index: number, count: number, direction: 1 | -1) => clampIndex(index + direction, count);

// Generated by rdloom codegen from specs/drawer.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** A modal panel that slides up from the bottom of the screen and can be dragged down to dismiss, for short tasks on phones. With snap points it also rests at several heights (a peek, half, nearly full) and is dragged between them. Open it with DialogTrigger. */
export interface DrawerSpecProps {
  /**
   * Heading, also used as the drawer accessible name. Without a title, pass aria-label.
   */
  title?: string;
  /**
   * Short supporting text under the title.
   */
  description?: string;
  /**
   * Draw the panel and its backdrop inside this element instead of over the whole page. Use it to show a sheet inside a preview, a framed app or a phone mock. The element must be positioned (relative) and clip its overflow.
   */
  portalContainer?: Element | null;
  /**
   * Closes on backdrop click and on a swipe or drag down. Esc always closes.
   * @default true
   */
  isDismissable?: boolean;
  /**
   * Heights the drawer can rest at, as shares of the available height (the screen, or the portalContainer): [0.4, 0.9] rests at 40% and 90%. They are kept between 0.1 and 1 and put in order. Drag the handle or header up and down to move between them; a drag down from the lowest closes it when isDismissable. Without snapPoints the drawer is as tall as its content, up to 90% of the screen.
   */
  snapPoints?: number[];
  /**
   * Which snap point is showing, as an index into the sorted snapPoints, to control it. Use with onSnapChange.
   */
  snap?: number;
  /**
   * Which snap point it opens at, as an index into the sorted snapPoints, when you do not control it.
   * @default 0
   */
  defaultSnap?: number;
  /**
   * Called with the new index when the drawer settles on another snap point.
   */
  onSnapChange?: (index: number) => void;
  /**
   * The words for the keyboard button that changes the height, for translation: { expand, collapse, expanded, collapsed }. Only used with two or more snap points.
   */
  labels?: Partial<Record<"expand" | "collapse" | "expanded" | "collapsed", string>>;
  /**
   * Body and actions. A function receives close().
   */
  children?: ReactNode | ((opts: { close: () => void }) => ReactNode);
}

export const drawerDefaults = {
  isDismissable: true,
  defaultSnap: 0,
} as const;

export const drawerMeta = {
  "name": "Drawer",
  "version": "0.1.0",
  "status": "experimental",
  "role": "dialog"
} as const;
